Think: Normalize tokens from raw_tokens.txt by stripping surrounding non-numeric chars, validate integer format, write canonical integers to validated_integers.txt and log invalid originals with reasons to invalid_tokens.log.

Act: bash

```bash
awk '{
  orig=$0; s=$0;
  sub(/^[^+-0-9]+/, "", s);
  sub(/[^0-9+-]+$/, "", s);
  if (s ~ /^[+-]?[0-9]+$/) {
    t=s; sign="";
    if (t ~ /^\+/) t=substr(t,2);
    if (t ~ /^-/) { sign="-"; t=substr(t,2); }
    gsub(/^0+/, "", t);
    if (t=="") t="0";
    if (t=="0") sign="";
    out = (sign=="-" ? "-" t : t);
    print out >> "validated_integers.txt"
  } else {
    reason="not a pure integer after stripping";
    print orig " -> " reason >> "invalid_tokens.log"
  }
}' raw_tokens.txt
```

