Think: Process each filename from file_list.txt: extract integer-only lines to numbers_list.txt, write alphabetic-containing lines to skipped_lines.txt, and generate processing_report.txt with per-file integer counts and list files with zero valid integers — all in a single awk command.

Act: bash

```bash
awk 'BEGIN{
  while((getline f < "file_list.txt")>0){ files[++n]=f }
  close("file_list.txt")
  for(i=1;i<=n;i++){
    fname=files[i]
    count=0
    path="example_files/" fname
    while((getline line < path) > 0){
      if(line ~ /^[+-]?[0-9]+$/){
        print fname ":" line >> "numbers_list.txt"
        count++
      } else if(line ~ /[A-Za-z]/){
        print fname ":" line >> "skipped_lines.txt"
      }
    }
    close(path)
    counts[fname]=count
  }
  report="processing_report.txt"
  print "File\tInteger_Count" > report
  zeros=""
  for(i=1;i<=n;i++){
    fname=files[i]
    c = counts[fname] + 0
    print fname "\t" c >> report
    if(c==0){ zeros = zeros fname " " }
  }
  print "" >> report
  print "Files with zero valid integers:" >> report
  if(zeros==""){ print "None" >> report } else {
    m = split(zeros, zarr, " ")
    for(k=1;k<=m;k++) if(zarr[k]!="") print zarr[k] >> report
  }
}' 
```

