  print "File\tInteger_Count" > "processing_report.txt"
  for(i=1;i<ARGC;i++){
    f=ARGV[i]; sub(/^example_files\//,"",f)
    c = counts[f] + 0
    print f "\t" c >> "processing_report.txt"
    if(c==0) zero_list = (zero_list ? zero_list " " : "") f
