  print "" >> "processing_report.txt"
  print "Files with zero valid integers:" >> "processing_report.txt"
  if(zero_list=="") print "None" >> "processing_report.txt"
  else {
    n=split(zero_list,arr," ")
    for(j=1;j<=n;j++) if(arr[j]!="") print arr[j] >> "processing_report.txt"
  }
}' $(sed 's@^@example_files/@' file_list.txt)
